from pathlib import Path
import base64,gzip,json

DOCTOR_GZ_B64=''
root=Path('.')
(root/'doctor_who/doctor_who_cards.cardconjurer').write_bytes(gzip.decompress(base64.b64decode(DOCTOR_GZ_B64)))

p=root/'derevi/derevi_cards.cardconjurer'
data=json.loads(p.read_text(encoding='utf-8'))
changed=[]
for entry in data:
    key=entry.get('key'); d=entry.get('data',{})
    if 'Land' in d.get('text',{}).get('type',{}).get('text',''):
        rules=d.get('text',{}).get('rules',{})
        if 'noVerticalCenter' in rules:
            rules.pop('noVerticalCenter',None); changed.append((key,'vertical-center'))
    if key in {'Savannah','Tundra'}:
        for f in d.get('frames',[]):
            masks=f.get('masks') or []
            if any(m.get('name')=='Rules' for m in masks) and ('White' in f.get('name','') or f.get('name','').startswith('W ')):
                if f.get('opacity')!=60:
                    f['opacity']=60; changed.append((key,'white-rules-opacity'))
by={e['key']:e['data'] for e in data}
for k in ('Savannah','Tundra'):
    assert any(f.get('opacity')==60 and any(m.get('name')=='Rules' for m in (f.get('masks') or [])) for f in by[k]['frames']), k
for k,d in by.items():
    if 'Land' in d.get('text',{}).get('type',{}).get('text',''):
        assert 'noVerticalCenter' not in d.get('text',{}).get('rules',{}), k
p.write_text(json.dumps(data,ensure_ascii=False,separators=(',',':')),encoding='utf-8')

doc=json.loads((root/'doctor_who/doctor_who_cards.cardconjurer').read_text(encoding='utf-8'))
assert len(doc)==51 and len({e['key'] for e in doc})==51
byd={e['key']:e['data'] for e in doc}
for k,d in byd.items():
    if 'Land' in d.get('text',{}).get('type',{}).get('text',''):
        r=d['text']['rules']; assert 'noVerticalCenter' not in r; assert r['x']>=0.105-1e-9 and r['width']<=0.79+1e-9
for n in ['Flooded Strand','Scalding Tarn','Misty Rainforest','Windswept Heath','Marsh Flats','Polluted Delta','Arid Mesa']:
    names=[f['name'] for f in byd[n]['frames']]; assert sum('Pinline' in x for x in names)>=2 and sum('Rules' in x for x in names)>=2, n
for n in ['Crystal Quarry','The World Tree','Cascading Cataracts','Reflecting Pool','Mana Confluence','Plaza of Heroes']:
    assert any('Multicolored' in f['name'] for f in byd[n]['frames']), n
m=byd['Morophon, the Boundless']['text']['rules']; assert m['size']<=.029 and '\n{W}{U}{B}{R}{G}' in m['text']
for n in ['Esika, God of the Tree','The Prismatic Bridge']:
    assert byd[n]['version']=='modalRegular'; assert byd[n]['text']['flipsideType']['text'] in ('Enchantment','Creature')
print('Doctor Who faces:',len(doc)); print('Derevi targeted changes:',changed)
